180	/** A journal rumor points at an island (a sealed source) or at a sector (a recovery cache), never at a carrier. */
181	export type IntelLeadTarget = { readonly kind: "island"; readonly island: number } | { readonly kind: "sector"; readonly sector: number };
182	
183	export type IntelLeadReason = "start" | "fresh" | "targeted" | "replacement";
184	
185	/** The three triggers that may ask for a carrier sighting; a start never does. */
186	export type CarrierSightingReason = Exclude<IntelLeadReason, "start">;
187	
188	/** One journal entry. `entry` numbers a player's rumors from 1. */
189	export interface JournalRumor {
190	  readonly entry: number;
191	  readonly type: RubbingType;
192	  readonly target: IntelLeadTarget;
193	  readonly reason: IntelLeadReason;
194	  readonly tick: number;
195	  /** `stale` once the target no longer holds that type; `resolved` once the holder has the type. */
196	  readonly status: "active" | "stale" | "resolved";
197	  readonly closedTick: number | null;
198	}
199	
200	/** One type of a deferred sighting: the free trigger (a loss or a journal replacement) that asked for it and when. */
201	export interface PendingSightingType {
202	  readonly type: RubbingType;
203	  readonly reason: "fresh" | "replacement";
204	  readonly tick: number;
205	}
206	
207	/**
208	 * The one deferred carrier-sighting message a player may have: the types whose free trigger met the cap, or found no
209	 * snapshot entry to read, waiting for the next snapshot boundary. A step's capped free triggers add their types to the set.
210	 */
211	export interface PendingSighting {
212	  /** In type order, each type once, never empty. */
213	  readonly types: readonly PendingSightingType[];
214	}
215	
216	export interface IntelPlayerState {
217	  readonly id: string;
218	  /** The held types as of the last processed tick, in type order; losses and completions are diffs of these. */
219	  readonly held: readonly RubbingType[];
220	  readonly journal: readonly JournalRumor[];
221	  /** Whether the player's final-island route is active (they hold a full set) and whether they ever had one. */
222	  readonly routeActive: boolean;
223	  readonly routeEver: boolean;
224	  /** The boundary of the snapshot current when the player last got a carrier sighting, or -1. */
225	  readonly lastSightingBoundary: number;
226	  /** The deferred sighting message, or null. */
227	  readonly pending: PendingSighting | null;
228	}
229	
230	/** One carried copy at a snapshot. The holder is kept only so a player is never shown their own copy. */
231	export interface CarrierSnapshotEntry {
232	  readonly sector: number;
233	  readonly type: RubbingType;
234	  readonly holder: string;
235	}
236	
237	export interface CarrierSnapshot {
238	  /** k for the boundary `controlStartTick + k × carrierIntervalTicks`. */
239	  readonly boundary: number;
240	  /** The tick whose world view it records (the boundary tick unless ticks were skipped). */
241	  readonly tick: number;
242	  readonly entries: readonly CarrierSnapshotEntry[];
243	}
244	
245	/** The information state: plain integer data that `hashState` covers entirely. */
246	export interface IntelState {
247	  /** The last world tick processed. */
248	  readonly tick: number;
249	  /** The seed of every draw: each (player, type) decision draws from a generator keyed by it, the tick, the player and the type. */
250	  readonly rng: number;
251	  /** Whether control start has been processed. */
252	  readonly started: boolean;
253	  /** Players seen in the last view, by id. */
254	  readonly players: readonly IntelPlayerState[];
255	  /** The latest two snapshots, older first. */
256	  readonly snapshots: readonly CarrierSnapshot[];
